import { PrismaClient, StudyLevel } from "@prisma/client";

const prisma = new PrismaClient();

type TopicSeed = {
  title: string;
  slug: string;
  description?: string;
  shortDescription?: string;
  estimatedMinutes: number;
  sections?: Array<{ title: string; content: string }>;
};

type ModuleSeed = {
  title: string;
  slug: string;
  description: string;
  topics?: TopicSeed[];
};

type PathSeed = {
  name: string;
  slug: string;
  description: string;
  level: StudyLevel;
  modules: ModuleSeed[];
};

type CategorySeed = {
  name: string;
  slug: string;
  description: string;
  icon: string;
  sortOrder: number;
  paths: PathSeed[];
};

function buildUltraDetailedSection(
  topic: TopicSeed,
  module: ModuleSeed,
  path: PathSeed,
  category: CategorySeed,
) {
  const title = topic.title.trim();
  const description = (topic.description ?? topic.shortDescription ?? "").trim();
  const subject = description || `the concepts covered by ${title}`;
  const lower = `${title} ${subject}`.toLowerCase();

  let mentalModel =
    `Start with the problem that **${title}** solves. In the **${category.name}** course, this topic belongs to the **${path.name}** learning path and the **${module.title}** module. ` +
    `A learner should first understand the purpose, then the mechanism, then the practical consequences. ` +
    `Do not memorize the definition alone: be able to explain what happens, why it happens, when the technique is appropriate, and what can go wrong.`;

  if (/(html|css|web|browser|dom|accessibility|seo|http|api|rest|frontend|responsive)/.test(lower)) {
    mentalModel +=
      " For web topics, connect the concept to what the browser receives, parses, computes, renders, and exposes to users. Consider semantics, accessibility, responsive behavior, performance, security, and maintainability.";
  } else if (/(java|spring|kotlin|android|jvm|thread|concurr|exception|collection|stream|lambda)/.test(lower)) {
    mentalModel +=
      " For JVM and application topics, connect the concept to language rules, runtime behavior, memory, concurrency, API design, error handling, and production maintainability.";
  } else if (/(sql|database|postgres|mysql|mongo|mongodb|redis|cache|transaction|index)/.test(lower)) {
    mentalModel +=
      " For database topics, reason about data modeling, correctness, query behavior, indexes, transactions, consistency, concurrency, failure recovery, and operational cost.";
  } else if (/(docker|kubernetes|devops|aws|cloud|linux|network|dns|tcp|udp|deployment|ci|cd)/.test(lower)) {
    mentalModel +=
      " For infrastructure topics, trace the complete path from configuration to runtime behavior. Include networking, resources, observability, failure modes, security boundaries, and recovery.";
  } else if (/(algorithm|data structure|tree|graph|sort|search|complexity|dynamic programming|recursion)/.test(lower)) {
    mentalModel +=
      " For algorithmic topics, identify the input constraints first, then the invariant or strategy, time complexity, space complexity, correctness argument, and the cases that break a naive solution.";
  } else if (/(machine learning|deep learning|model|neural|regression|classification|feature|training|embedding|llm|generative ai)/.test(lower)) {
    mentalModel +=
      " For AI/ML topics, separate the problem definition, data, representation, training objective, evaluation metric, inference behavior, failure modes, and deployment constraints.";
  } else if (/(security|cyber|authentication|authorization|encryption|vulnerability|attack|threat)/.test(lower)) {
    mentalModel +=
      " For security topics, identify the asset, trust boundary, threat, attack path, control, residual risk, and verification method. Prefer defense-in-depth over relying on one control.";
  } else if (/(hr|interview|presales|sales|behavioral|leadership|communication)/.test(lower)) {
    mentalModel +=
      " For role and behavioral topics, focus on a clear situation, the decision you made, the reasoning behind it, the measurable outcome, and what you learned or would improve.";
  }

  const keyPoints = [
    `Purpose: Explain what ${title} is designed to solve and the problem it addresses.`,
    `Mechanism: Describe the important steps, components, lifecycle, or rules involved in ${title}.`,
    `Practical use: Give one realistic example and explain why this approach fits the requirement.`,
    `Trade-offs: Compare the main benefit with at least one limitation, cost, or alternative.`,
    `Failure handling: Explain a common incorrect usage or failure mode and how you would detect and fix it.`,
    `Validation: State how you would test, measure, debug, or verify the expected behavior.`,
  ];

  if (/(performance|optimi|scale|latency|throughput|complexity)/.test(lower)) {
    keyPoints.push(
      "Performance lens: identify the dominant cost, measure it with realistic workloads, and optimize only after confirming the bottleneck."
    );
  }

  if (/(security|auth|permission|password|token|secret|api key|injection)/.test(lower)) {
    keyPoints.push(
      "Security lens: validate untrusted input, enforce authorization at the correct boundary, protect secrets, and log security-relevant failures without leaking sensitive data."
    );
  }

  if (/(test|debug|error|exception|failure|troubleshoot)/.test(lower)) {
    keyPoints.push(
      "Diagnostics lens: reproduce the issue, isolate the smallest failing case, inspect evidence, apply one controlled change, and verify the fix with a regression test."
    );
  }

  const example = description
    ? `Suppose a project needs to address this requirement: ${description}. Start with the simplest implementation of **${title}**, verify the normal path, then deliberately test an edge case and an invalid input. The important part of the example is not the syntax; it is being able to explain why each decision was made and what evidence proves the implementation is correct.`
    : `Build a small example around **${title}**. Start with the happy path, then test an edge case and an invalid or unexpected input. Explain each meaningful step and what evidence confirms the result.`;

  return {
    title: "Ultra-Detailed Explanation & Interview Guide",
    content:
      `## 1. Core mental model\n\n${mentalModel}\n\n` +
      `## 2. What you must understand\n\n${keyPoints.map((x) => `- ${x}`).join("\n")}\n\n` +
      `## 3. Step-by-step learning path\n\n` +
      `1. **Define it:** Explain the topic in one or two precise sentences.\n` +
      `2. **Identify the moving parts:** Name the important APIs, components, rules, layers, or data involved.\n` +
      `3. **Trace the flow:** Describe what happens from input to result, including important intermediate steps.\n` +
      `4. **Use it:** Apply it to a small realistic example before thinking about advanced cases.\n` +
      `5. **Break it:** Try an edge case, invalid input, failure, or unexpected workload.\n` +
      `6. **Compare it:** Explain the closest alternative and why you would choose one over the other.\n` +
      `7. **Verify it:** State what test, measurement, log, debugger, benchmark, or review would give you confidence.\n\n` +
      `## 4. Practical example\n\n${example}\n\n` +
      `## 5. Common mistakes to avoid\n\n` +
      `- Memorizing terminology without being able to explain the mechanism.\n` +
      `- Giving an example that does not match the stated requirement.\n` +
      `- Ignoring edge cases, failure behavior, or invalid input.\n` +
      `- Claiming an approach is always faster, safer, or better without stating the conditions.\n` +
      `- Applying a pattern or tool where a simpler solution would be clearer.\n` +
      `- Failing to explain how the result would be tested or verified.\n\n` +
      `## 6. Troubleshooting approach\n\n` +
      `If **${title}** behaves unexpectedly, first reproduce the issue and define the expected behavior. Then isolate the smallest failing case, inspect the relevant inputs and runtime evidence, and determine whether the problem is caused by incorrect assumptions, configuration, data, lifecycle, concurrency, resource limits, or implementation. Change one variable at a time, verify the result, and add a regression test or operational safeguard so the same problem is less likely to return.\n\n` +
      `## 7. Interview-ready answer\n\n` +
      `A strong interview response should move from **definition → mechanism → example → trade-off → failure case → validation**. Keep the first answer concise, then expand only when the interviewer asks for depth. If challenged with a scenario, explain your reasoning and assumptions rather than jumping directly to a tool or code snippet.\n\n` +
      `## 8. Advanced questions to prepare\n\n` +
      `- What changes when the scale, workload, or constraints increase?\n` +
      `- What is the closest alternative, and what trade-off does it introduce?\n` +
      `- What is the most likely production failure mode?\n` +
      `- How would you test or measure this in a real system?\n` +
      `- What security, performance, reliability, or maintainability concern would you check first?\n\n` +
      `## 9. Practice task\n\n` +
      `Create a small working example for **${title}** in the **${module.title}** module. Record the normal result, one edge-case result, and one deliberately incorrect case. Explain the cause of each result and the production-quality improvement you would make.\n`,
  };
}

async function ensureCategory(category: CategorySeed) {
  const createdCategory = await prisma.studyCategory.upsert({
    where: { slug: category.slug },
    update: {
      name: category.name,
      description: category.description,
      icon: category.icon,
      isPublished: true,
      sortOrder: category.sortOrder,
    },
    create: {
      name: category.name,
      slug: category.slug,
      description: category.description,
      icon: category.icon,
      isPublished: true,
      sortOrder: category.sortOrder,
    },
  });

  for (const pathSeed of category.paths) {
    const path = await prisma.studyPath.upsert({
      where: { categoryId_slug: { categoryId: createdCategory.id, slug: pathSeed.slug } },
      update: {
        name: pathSeed.name,
        description: pathSeed.description,
        level: pathSeed.level,
        isPublished: true,
        sortOrder: 0,
      },
      create: {
        categoryId: createdCategory.id,
        name: pathSeed.name,
        slug: pathSeed.slug,
        description: pathSeed.description,
        level: pathSeed.level,
        isPublished: true,
        sortOrder: 0,
      },
    });

    for (const moduleSeed of pathSeed.modules) {
      const module = await prisma.studyModule.upsert({
        where: { studyPathId_slug: { studyPathId: path.id, slug: moduleSeed.slug } },
        update: {
          title: moduleSeed.title,
          description: moduleSeed.description,
          isPublished: true,
          sortOrder: 0,
        },
        create: {
          studyPathId: path.id,
          title: moduleSeed.title,
          slug: moduleSeed.slug,
          description: moduleSeed.description,
          isPublished: true,
          sortOrder: 0,
        },
      });

      for (const topicSeed of moduleSeed.topics ?? []) {
        const topic = await prisma.studyTopic.upsert({
          where: { categoryId_slug: { categoryId: createdCategory.id, slug: topicSeed.slug } },
          update: {
            title: topicSeed.title,
            moduleId: module.id,
            shortDescription: topicSeed.shortDescription ?? topicSeed.description ?? "",
            estimatedMinutes: topicSeed.estimatedMinutes,
            isPublished: true,
            sortOrder: 0,
          },
          create: {
            categoryId: createdCategory.id,
            moduleId: module.id,
            title: topicSeed.title,
            slug: topicSeed.slug,
            shortDescription: topicSeed.shortDescription ?? topicSeed.description ?? "",
            estimatedMinutes: topicSeed.estimatedMinutes,
            isPublished: true,
            sortOrder: 0,
            prerequisiteIds: [],
            relatedTopicIds: [],
          },
        });

        const sourceSections = topicSeed.sections ?? [];
        const ultra = buildUltraDetailedSection(topicSeed, moduleSeed, pathSeed, category);
        const sections = [...sourceSections, ultra];

        for (let index = 0; index < sections.length; index += 1) {
          const section = sections[index];
          await prisma.studyTopicSection.upsert({
            where: { id: `${topic.id}-section-${index}` },
            update: {
              title: section.title,
              content: section.content,
              sortOrder: index,
            },
            create: {
              id: `${topic.id}-section-${index}`,
              topicId: topic.id,
              title: section.title,
              content: section.content,
              sortOrder: index,
            },
          });
        }
      }
    }
  }
}

